template <typename T, typename S, typename U>
rocblas_status run_steqr_hybrid(rocblas_handle handle,
                                rocblas_int n,
                                S* dD,
                                const rocblas_stride strideD,
                                S* dE,
                                const rocblas_stride strideE,
                                U dC,
                                const rocblas_stride shiftC,
                                const rocblas_int ldc,
                                const rocblas_stride strideC,
                                const rocblas_int batch_count,
                                rocblas_int* dInfo,
                                S* dWork,
                                const rocblas_int max_iters,
                                const S eps,
                                const S ssfmin,
                                const S ssfmax,
                                const bool ordered = true)

if((evect != rocblas_evect_original && evect != rocblas_evect_none)
   || (uplo != rocblas_fill_lower && uplo != rocblas_fill_upper))
    return rocblas_status_invalid_value;

if(n < 0 || lda < n || batch_count < 0)
    return rocblas_status_invalid_size;

if((n && !A) || (n && !E) || (n && !D) || (batch_count && !info))
    return rocblas_status_invalid_pointer;
